// all returns the matching rows, with the requested edges.
pub fn (q ArticleQuery) all() ![]ArticleNode {
	rows := load.select_where[models.Article](q.graph.client.conn, q.graph.client.prepare_query('articles', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q ArticleQuery) first() !ArticleNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'articles'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q ArticleQuery) nodes(rows []models.Article) ![]ArticleNode {
	mut nodes := rows.map(ArticleNode{
		graph:   q.graph
		article: it
	})
	if q.with_author {
		found := q.load_author(rows, q.author_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.article.id.str()] or { [] }
			if list.len > 0 {
				node.author = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'author'
		}
	}
	if q.with_comments {
		found := q.load_comments(rows, q.comments_fns)!
		for mut node in nodes {
			node.comments = found[node.article.id.str()] or { [] }
			node.loaded << 'comments'
		}
	}
	for name, fns in q.named_comments {
		found := q.load_comments(rows, fns)!
		for mut node in nodes {
			node.named_comments[name] = found[node.article.id.str()] or { [] }
		}
	}
	if q.with_tags {
		found := q.load_tags(rows, q.tags_fns)!
		for mut node in nodes {
			node.tags = found[node.article.id.str()] or { [] }
			node.loaded << 'tags'
		}
	}
	for name, fns in q.named_tags {
		found := q.load_tags(rows, fns)!
		for mut node in nodes {
			node.named_tags[name] = found[node.article.id.str()] or { [] }
		}
	}
	return nodes
}

// load_author loads the `author` of `rows`, keyed by each row's key.
fn (q ArticleQuery) load_author(rows []models.Article, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.user_id.str()
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_edge_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.user_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// author_or_err returns the `author`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n ArticleNode) author_or_err() !&UserNode {
	if 'author' !in n.loaded {
		return NotLoadedError{
			edge: 'articles.author'
		}
	}
	if target := n.author {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// load_comments loads the `comments` of `rows`, keyed by each row's key.
fn (q ArticleQuery) load_comments(rows []models.Article, fns []fn (CommentQuery) CommentQuery) !map[string][]CommentNode {
	mut sub := q.graph.comments()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[models.Comment](q.graph.client.conn, 'article_id',
		rows.map(it.id.str()),
		query: q.graph.client.prepare_edge_query('comments', sub.query)!
	)!)!
	mut by_parent := map[string][]CommentNode{}
	for child in children {
		by_parent[child.comment.article_id.str()] << child
	}
	return by_parent
}

// comments_or_err returns the `comments`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n ArticleNode) comments_or_err() ![]CommentNode {
	if 'comments' !in n.loaded {
		return NotLoadedError{
			edge: 'articles.comments'
		}
	}
	return n.comments
}

// load_tags loads the `tags` of `rows`, keyed by each row's key.
fn (q ArticleQuery) load_tags(rows []models.Article, fns []fn (TagQuery) TagQuery) !map[string][]TagNode {
	mut sub := q.graph.tags()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('tags', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'article_tags', 'article_id', 'tag_id',
			rows.map(it.id.str()), .i64, .int, 'tags', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Tag](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]TagNode{}
		for target in found {
			by_key[target.tag.id.str()] = target
		}
		mut cut_linked := map[string][]TagNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'article_tags', 'article_id',
		'tag_id', rows.map(it.id.str()), .i64, .int)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]TagNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Tag](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('tags', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.tag.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

// tags_or_err returns the `tags`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n ArticleNode) tags_or_err() ![]TagNode {
	if 'tags' !in n.loaded {
		return NotLoadedError{
			edge: 'articles.tags'
		}
	}
	return n.tags
}

// query_author starts a query of this row's `author`, which matches
// nothing when the row has none.
pub fn (n ArticleNode) query_author() UserQuery {
	key := n.article.user_id
	return n.graph.users().where(load.eq('id', key))
}

// query_comments starts a query of this row's `comments`.
pub fn (n ArticleNode) query_comments() CommentQuery {
	return n.graph.comments().where(load.eq('article_id', n.article.id))
}

// query_tags starts a query of this row's `tags`. It reads the join
// table `article_tags` first, so it can fail.
pub fn (n ArticleNode) query_tags() !TagQuery {
	pairs := load.link_pairs(n.graph.client.conn, 'article_tags', 'article_id',
		'tag_id', [n.article.id.str()], .i64, .int)!
	return n.graph.tags().where(load.in_keys('id', pairs.map(it[1]), .int))
}
